Translate("deDE", "shadowfang-keep", {
	title = "Burg Shadowfang",
	aliases = { "Shadowfang" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Burg Shadowfang steht auf einem dunklen Hügel im südlichen {link:silverpine-forest}Silberwald{/link}, über dem Weiler {link:pyrewood-village}Pyrewood{/link}. Einst war sie der Sitz des edlen Barons {link:baron-silverlaine}Silverlaine{/link}. Nun ist sie der Hort von {link:archmage-arugal}Erzmagier Arugal{/link} und der Worgen, die er seine Kinder nennt. Wolfsmenschen streifen durch ihre Hallen, Worgs heulen in ihren Höfen, und die Toten des Haushalts des Barons wandeln noch immer durch die Räume, in denen sie erschlagen wurden.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Im {link:third-war}Dritten Krieg{/link} kämpften die Zauberer der {link:kirin-tor}Kirin Tor{/link} im Norden gegen die {link:scourge}Geißel{/link}. Jeder Zauberer, der fiel, erhob sich bald wieder, um für den Feind zu kämpfen, und die Geißel wuchs nur. {link:archmage-arugal}Arugal{/link} wollte das nicht hinnehmen. Gegen den Rat seiner Gefährten rief er Wesen von jenseits der Welt herbei, um die schwindenden Reihen {link:dalaran}Dalaran{/link}s aufzufüllen. Was seinem Ruf folgte, waren die {red:worgen}Worgen{/red}. Die gierigen Wolfsmenschen zerfetzten die Untoten und wandten sich dann gegen die Zauberer selbst. Sie belagerten die Burg des Barons {link:baron-silverlaine}Silverlaine{/link}, und sie verfiel in Schatten und Trümmer. Von Schuld in den Wahnsinn getrieben, nahm Arugal die Worgen als seine eigenen Kinder an. Er zog sich in die gefallene Burg zurück und gab ihr einen neuen Namen: Shadowfang.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die {link:forsaken}Verlassenen{/link} können den {link:silverpine-forest}Silberwald{/link} nicht halten, solange {link:archmage-arugal}Arugal{/link} lebt, und sie haben geschworen, ihn tot zu sehen. {link:high-executor-hadrec}Hochexekutor Hadrec{/link} schickte zwei Todespirscher in die Burg, um ihre Geheimnisse zu erkunden. Sie kehrten nicht zurück. Auch die {link:kirin-tor}Kirin Tor{/link} haben ihren eigenen Agenten geschickt, und ihm erging es nicht besser. Beide warten nun in Zellen nahe dem Tor. {link:keeper-bel-dugur}Bewahrer Bel'dugur{/link} aus {link:undercity}Undercity{/link} will ein Buch, das irgendwo in der Burg liegt, das Werk eines Magiers aus {link:dalaran}Dalaran{/link} namens Ur, der andere Welten erforschte. Im {link:the-sepulcher}Grabmal{/link} behauptet nun ein toter Erzmagier, Arugal habe die Worgen überhaupt nicht erschaffen.]=],
		},
		{
			title = "In der Burg",
			text = [=[• {b}Die Zellen.{/b} Nahe dem Eingang hält der Worg {link:rethilgore}Rethilgore{/link} seine Gefangenen eingesperrt.
• {b}Der Burghof.{/b} Hinter einer versiegelten Tür liegt der innere Hof, wo die toten Soldaten der Burg und Arugals Worgen gemeinsam Wache halten.
• {b}Die Hallen des Haushalts.{/b} {link:razorclaw-the-butcher}Razorclaw der Schlächter{/link} arbeitet in den Küchen. Der Geist von {link:baron-silverlaine}Baron Silverlaine{/link} sucht den Speisesaal heim, und {link:commander-springvale}Kommandant Springvale{/link} hält mit seinen toten Offizieren einen Ratssaal.
• {b}Die Höhen.{/b} {link:odo-the-blindwatcher}Odo der Blindseher{/link} hält seinen Ausguck hoch oben auf den Mauern. {link:wolf-master-nandos}Wolfsmeister Nandos{/link} lässt sein Rudel über den oberen Hof jagen, und {link:fenrus-the-devourer}Fenrus der Verschlinger{/link} bewacht die Gemächer seines Herrn.
• {b}Arugals Zuflucht.{/b} An der Spitze der Burg wartet der Erzmagier inmitten seiner Diener.]=],
		},
	},
})

Translate("deDE", "archmage-arugal", {
	title = "Erzmagier Arugal",
	subtitle = "Herr von Burg Shadowfang",
	found = "Die höchsten Hallen von Burg Shadowfang",
	hint = [=[Erfahrt im Grabmal von ihm oder steigt zur Spitze von Burg Shadowfang hinauf.]=],
	allegiance = "Söhne Arugals · einst die Kirin Tor",
	aliases = { "Arugal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Arugal war ein Erzmagier der {link:kirin-tor}Kirin Tor{/link} von {link:dalaran}Dalaran{/link}. Im {link:third-war}Dritten Krieg{/link}, als die Zauberer seines Ordens starben und sich für die {link:scourge}Geißel{/link} wieder erhoben, rief er die {red:worgen}Worgen{/red} herbei, um für sie zu kämpfen. Die Worgen metzelten die Toten nieder und wandten sich dann gegen die Lebenden. Von Schuld in den Wahnsinn getrieben, nahm Arugal die Bestien als seine Söhne an, bemächtigte sich der Burg des Barons {link:baron-silverlaine}Silverlaine{/link} und nannte sie {link:shadowfang-keep}Burg Shadowfang{/link}. Von dort hat sich sein Fluch über den ganzen {link:silverpine-forest}Silberwald{/link} ausgebreitet.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Arugal ist die Wurzel der Worgenplage im {link:silverpine-forest}Silberwald{/link}. Seine Fesseln binden die Dorfbewohner von {link:pyrewood-village}Pyrewood{/link}, seine Magie verseuchte die Bergleute der {link:deep-elem-mine}Tiefenfelsmine{/link}, und seine Söhne machen Jagd auf den Straßen. Für die {link:forsaken}Verlassenen{/link} ist er das letzte große Hindernis für ihre Herrschaft über den Wald.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hielt sich zuerst auf einem Weizenhof im nördlichen {link:silverpine-forest}Silberwald{/link} auf und ließ dort seine Zauberbücher zurück.
• Er rief die Worgen gegen den Willen seiner Gefährten herbei.
• Er verfluchte das Dorf {link:pyrewood-village}Pyrewood{/link} und beherrscht es durch seinen Rat.
• Er nahm die Burg des Barons {link:baron-silverlaine}Silverlaine{/link} ein und machte ihre Toten zu seinem Haushalt.
• Er hält eine große Bestie, {link:fenrus-the-devourer}Fenrus{/link}, und Diener des Schattens von jenseits der Welt.
• Im Kampf verflucht er seine Feinde in die Gestalt von Worgen und lässt Leerenblitze und Donner auf sie niedergehen.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Keine Chronik dieser Tage verzeichnet Arugals Leben vor dem Dritten Krieg oder woher seine Worgen wirklich kamen.]=],
		},
	},
	chapters = {
		{
			title = "Das Heilmittel",
			hint = [=[Holt den Zauber des Erzmagiers von dem Hof zurück, auf dem er einst weilte.]=],
			text = [=[Unter den Büchern, die Arugal auf dem Hof zurückließ, war ein Zauber, den er sein Heilmittel nannte. {link:dalar-dawnweaver}Dalar Dawnweaver{/link}, der die {link:kirin-tor}Kirin Tor{/link} von innen gekannt hatte, las ihn mit Verachtung. Er fragte sich laut, wie ein solcher Mann je in den Orden aufgenommen worden war. Arugals Zauber, sagte er, seien so dünn, dass jeder Lehrling sie durchschauen könne.]=],
		},
		{
			title = "Die Fesseln von Pyrewood",
			hint = [=[Bringt die Fesseln von Pyrewood zum toten Erzmagier im Grabmal.]=],
			text = [=[Arugal glich die Schwäche seiner Magie mit verzauberten Dingen aus. Jeder Worg der Moonrage trug seine Fessel, und ebenso jeder Dorfbewohner von {link:pyrewood-village}Pyrewood{/link}, die bei Tag {link:humans}Menschen{/link} und bei Nacht Bestien waren. Aus diesen Fesseln zog {link:dalar-dawnweaver}Dalar{/link} die Macht, die er brauchte, um den Fluch zu verstehen.]=],
		},
		{
			title = "Der Betrüger",
			hint = [=[Helft dem toten Erzmagier, seine Behauptung mit Überresten vom Greymane-Wall zu beweisen.]=],
			text = [=[Mit der Zeit gelangte {link:dalar-dawnweaver}Dalar{/link} zu einem Urteil, das niemand erwartet hatte. Die Fesseln bewiesen, dass Arugal die Worgen binden konnte. Sie bewiesen nicht, dass er sie erschaffen hatte. Sein berühmter Fluch war zu schwach, um zu bestehen. Die Worgen, sagte Dalar, verbreiteten ihren Fluch auf andere Weise.]=],
		},
		{
			title = "Der Tod Arugals",
			hint = [=[Steigt zur Spitze von Burg Shadowfang hinauf und beendet die Zauber des Erzmagiers.]=],
			text = [=[{link:dalar-dawnweaver}Dalar{/link} wollte nicht zulassen, dass {link:sylvanas-windrunner}die Dunkle Fürstin{/link} den {link:silverpine-forest}Silberwald{/link} beanspruchte, solange Arugal lebte, und er ließ nach dem Kopf des Erzmagiers schicken. An der Spitze seiner Burg, inmitten seiner Diener und seiner Söhne, wurde Arugal erschlagen. Sein Kopf wurde zurück ins {link:the-sepulcher}Grabmal{/link} getragen.]=],
		},
	},
	mentions = {
		{ text = "Arugals Torheit, das Heilmittel" },
		{ text = "Arugals Torheit, die Fesseln" },
		{ text = "Arugals Torheit, ein neues Urteil" },
		{ text = "Haltet die Ausbreitung auf" },
		{ text = "Hinterhalt in {link:pyrewood-village}Pyrewood{/link}" },
		{ text = "Arugal muss sterben" },
	},
	bonds = {
		{ id = "dalar-dawnweaver", name = "Dalar Dawnweaver", note = "verachtet ihn" },
		{ id = "baron-silverlaine", name = "Baron Silverlaine", note = "sucht seine Burg heim" },
		{ id = "fenrus-the-devourer", name = "Fenrus der Verschlinger", note = "seine große Bestie" },
		{ id = "pyrewood-villagers", name = "Dorfbewohner von Pyrewood", note = "von ihm verflucht" },
		{ id = "apothecary-berard", name = "Apotheker Berard", note = "verlor durch den Fluch den Verstand" },
	},
})

Translate("deDE", "baron-silverlaine", {
	title = "Baron Silverlaine",
	subtitle = "Der rachsüchtige Geist",
	found = "Der Speisesaal von Burg Shadowfang",
	hint = [=[Sucht den Geist des alten Herrn der Burg in ihrem Speisesaal.]=],
	allegiance = "Haus Silverlaine",
	aliases = { "Silverlaine" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Baron Silverlaine war der edle Herr der Burg, die über {link:pyrewood-village}Pyrewood{/link} steht. Als Arugals Worgen kamen, belagerten sie sein Heim, und es fiel. Silverlaine starb mit ihm. Er fand keine Ruhe. Sein Geist wandelt durch den Speisesaal, in dem er einst tafelte, zwischen den toten Dienern seines Haushalts, und er richtet seinen Zorn gegen jeden, der dort eindringt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Silverlaine ist das erste Opfer von Arugals Torheit innerhalb der Burg und ihr rechtmäßiger Herr. Die Burg war sein, bevor sie {link:shadowfang-keep}Shadowfang{/link} wurde. Sie verfiel schnell in Schatten und Trümmer, und die Worgen, die sie einnahmen, streifen nun durch die Räume um seinen Saal. Sein rachsüchtiger Geist erinnert daran, dass der Erzmagier seine Zuflucht auf den Gräbern anderer errichtete.]=],
		},
		{
			title = "Taten",
			text = [=[• Seine Burg wurde von den Worgen belagert, und sie fiel.
• Sein Haushalt starb mit ihm, und seine Toten dienen noch immer in den Hallen.
• Im Tod legt er einen Schleier aus Schatten über seine Feinde, der jede heilende Berührung schwächt.
• Er trägt noch immer das Siegel seiner Familie.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Keine Chronik dieser Tage verzeichnet den Vornamen des Barons, seine Familie oder den Herrn, dem er diente. Es steht nicht geschrieben, warum sein Geist bleibt, wo so viele andere gegangen sind.]=],
		},
	},
	chapters = {
		{
			title = "Der Herr des Speisesaals",
			hint = "Stellt Euch dem Geist des Barons in seinem eigenen Saal.",
			text = [=[Die Toten des Haushalts sind noch immer an die Burg gebunden. Diener und Wachen klagen in ihren Hallen, und {link:the-baron}der Baron{/link} wandelt zwischen ihnen in seinem Speisesaal. Er konnte die Worgen nicht von seinem Haus fernhalten. Er hat keinem vergeben, der es seither betreten hat.]=],
		},
	},
	mentions = {
		{ text = "{link:archmage-arugal}Arugal{/link} muss sterben" },
	},
	bonds = {
		{ id = "archmage-arugal", name = "Erzmagier Arugal", note = "nahm ihm seine Burg" },
		{ id = "commander-springvale", name = "Kommandant Springvale", note = "befehligt seine toten Soldaten" },
	},
})

Translate("deDE", "commander-springvale", {
	title = "Kommandant Springvale",
	subtitle = "Kommandant der toten Wache",
	found = "Ein Ratssaal in Burg Shadowfang",
	hint = [=[Stellt Euch dem toten Kommandanten, der in der Burg noch immer seinen Posten hält.]=],
	allegiance = "Haus Silverlaine",
	aliases = { "Springvale" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kommandant Springvale führte die Soldaten des Barons {link:baron-silverlaine}Silverlaine{/link}. Als die Worgen die Burg stürmten, fiel er auf seinem Posten, und er erhob sich wieder als einer ihrer Toten. Er hält noch immer einen Ratssaal mit seinen gequälten Offizieren, und die Geister seiner Wachen klagen durch die Hallen um ihn herum.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Springvale war im Leben ein Diener des {link:holy-light}Heiligen Lichts{/link}, und das Licht hat ihn nicht ganz verlassen. Er heilt noch immer seine Wunden damit, schirmt sich damit ab und streckt seine Feinde mit dem Hammer der Gerechtigkeit nieder. Es ist ein bitterer Anblick: ein Verteidiger der Burg, durch den Tod zu einem weiteren {link:the-night-watch}Wächter{/link} von Arugals Hort geworden. Er ist mit diesem Schicksal nicht allein. Gequälte Offiziere stehen an seiner Seite, klagende Wachen wandeln durch die Hallen, und heimgesuchte Diener hüten noch immer die Räume eines Herrn, der fort ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befehligte die Soldaten des Barons.
• Er starb beim Fall der Burg.
• Er hält mit seinen Offizieren noch immer Wache über Räume, die nicht mehr seinem Herrn gehören.]=],
		},
		{
			title = "Unaufgezeichnet",
			text = [=[Keine Chronik dieser Tage verzeichnet Springvales Namen vor der Burg oder wo er lernte, das Licht zu führen.]=],
		},
	},
	chapters = {
		{
			title = "Die letzte Wache",
			hint = "Stellt Euch dem toten Kommandanten und seinen Offizieren.",
			text = [=[Die Burg ist gefallen, und sein Herr ist tot. Springvale hält dennoch seinen Posten, mit seinen Offizieren an seiner Seite. Wenn Fremde eintreten, ruft er das Licht gegen sie an, wie er es gegen die Worgen tat.]=],
		},
	},
	mentions = {
		{ text = "{link:archmage-arugal}Arugal{/link} muss sterben" },
	},
	bonds = {
		{ id = "baron-silverlaine", name = "Baron Silverlaine", note = "sein Herr" },
		{ id = "archmage-arugal", name = "Erzmagier Arugal", note = "Herr der Burg, für die er starb" },
	},
})

Translate("deDE", "rethilgore", {
