			text = [=[Rethilgore ist der Worg, der die Zellen von {link:shadowfang-keep}Burg Shadowfang{/link} bewacht. Wer in Arugals Reich eindringt und am Leben bleibt, landet in seiner Obhut. Er entzieht seinen Feinden das Leben und nährt sich davon.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Rethilgore bewacht zwei Gefangene rivalisierender Herren: einen Todespirscher der Verlassenen und einen Zauberer der {link:kirin-tor}Kirin Tor{/link}. Sie sind sich in nichts einig, außer darin, dass der Kerkermeister den Tod verdient. Seine Zellen sind besser gebaut als die übrigen Türen der Burg. Selbst der Zauberer, der diese Türen mit Leichtigkeit öffnet, konnte ihnen nicht entkommen.]=],
		},
	},
	mentions = {
		{ text = "Todespirscher in {link:shadowfang-keep}Shadowfang{/link}" },
	},
	bonds = {
		{ id = "deathstalker-adamant", name = "Todespirscher Adamant", note = "sein Gefangener" },
		{ id = "sorcerer-ashcrombe", name = "Zauberer Ashcrombe", note = "sein Gefangener" },
	},
})

