	allegiance = "Verlassene · Todespirscher",
	aliases = { "Adamant" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Todespirscher Adamant war einer von zwei Agenten, die {link:high-executor-hadrec}Hochexekutor Hadrec{/link} vor einem Angriff in {link:shadowfang-keep}Burg Shadowfang{/link} schickte, um Kunde zu sammeln. Er wurde gefasst und in eine Zelle geworfen. Sein Partner, Todespirscher Vincent, hatte weniger Glück. Vincents zerschmetterter Leib liegt in der Burg, und was er erfahren hatte, starb mit ihm.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Adamant ist der Schlüssel der Verlassenen zur Burg. Befreit führt er seine Retter zum Burghof und öffnet dessen Tür. Dann eilt er mit seinem Bericht zurück zu {link:high-executor-hadrec}Hadrec{/link}.]=],
		},
	},
	mentions = {
		{ text = "Todespirscher in {link:shadowfang-keep}Shadowfang{/link}" },
	},
	bonds = {
		{ id = "high-executor-hadrec", name = "Hochexekutor Hadrec", note = "schickte ihn aus" },
		{ id = "sorcerer-ashcrombe", name = "Zauberer Ashcrombe", note = "sein Mitgefangener" },
		{ id = "rethilgore", name = "Rethilgore", note = "hielt ihn gefangen" },
	},
})

